  gorsel: "<table class=\"tablo\"><tr><th colspan=\"6\">Tablo: Turnuva puan durumu</th></tr><tr><th>Takım</th><th>Oynadığı</th><th>Galibiyet</th><th>Beraberlik</th><th>Mağlubiyet</th><th>Puan</th></tr><tr><td>Yıldız</td><td>5</td><td>3</td><td>1</td><td>1</td><td>10</td></tr><tr><td>Kartal</td><td>5</td><td>2</td><td>2</td><td>1</td><td>8</td></tr><tr><td>Aslan</td><td>5</td><td>1</td><td>3</td><td>1</td><td>6</td></tr><tr><td>Şimşek</td><td>5</td><td>1</td><td>1</td><td>3</td><td>4</td></tr></table>",
